package typegen

import (
	"cmp"
	"context"
	"encoding/json/jsontext"
	"errors"
	"fmt"
	"go/constant"
	"go/types"
	"io/fs"
	"log/slog"
	"maps"
	"os"
	"path/filepath"
	"regexp"
	"slices"
	"strings"

	"github.com/matthewmueller/jig/internal/directory"
	"github.com/matthewmueller/jig/internal/gitignore"
	"golang.org/x/tools/go/packages"
)

// header starts every generated file. Files without it are never overwritten
// or removed.
const header = "// Code generated by jig. DO NOT EDIT.\n"

// Generate writes a <file>.go.ts next to each Go file in dir with the types it
// declares, so views can import them from the Go file, like "./props.go". The
// types match how encoding/json/v2 marshals them.
func Generate(ctx context.Context, log *slog.Logger, dir string) error {
	dir, err := directory.Resolve(dir)
	if err != nil {
		return fmt.Errorf("typegen: unable to resolve directory: %w", err)
	}
	pkgDirs, existing, err := walk(dir)
	if err != nil {
		return fmt.Errorf("typegen: unable to walk %s: %w", dir, err)
	}
	outputs := map[string]string{}
	if len(pkgDirs) > 0 {
		decls, err := load(ctx, dir, pkgDirs)
		if err != nil {
			return err
		}
		outputs, err = generate(log, decls)
		if err != nil {
			return err
		}
	}
	return write(outputs, existing)
}

// walk dir for the directories with Go packages and the existing .go.ts files
func walk(dir string) (pkgDirs, existing []string, err error) {
	ignored := gitignore.From(dir)
	err = filepath.WalkDir(dir, func(path string, de fs.DirEntry, err error) error {
		if err != nil || path == dir {
			return err
		}
		name := de.Name()
		if de.IsDir() {
			// Skip what the go command skips. Patterns can't cross into nested
			// modules either.
			if ignored(path) || name == "testdata" || strings.HasPrefix(name, ".") || strings.HasPrefix(name, "_") {
				return filepath.SkipDir
			}
			if _, err := os.Stat(filepath.Join(path, "go.mod")); err == nil {
				return filepath.SkipDir
			} else if !errors.Is(err, fs.ErrNotExist) {
				return err
			}
			return nil
		}
		switch {
		case ignored(path):
		case strings.HasSuffix(name, ".go.ts"):
			existing = append(existing, path)
		case strings.HasSuffix(name, ".go") && !strings.HasSuffix(name, "_test.go"):
			if pkgDir := filepath.Dir(path); !slices.Contains(pkgDirs, pkgDir) {
				pkgDirs = append(pkgDirs, pkgDir)
			}
		}
		return nil
	})
	return pkgDirs, existing, err
}

// decl is an exported type declared in the views directory
type decl struct {
	obj  *types.TypeName
	file string // Go file it's declared in
	deps []key  // decls it references
	err  error  // why it can't be generated
}

// key identifies a named type. Packages can be loaded more than once, so their
// objects can't be compared directly.
type key struct {
	pkg  string
	name string
}

func keyOf(obj *types.TypeName) key {
	return key{obj.Pkg().Path(), obj.Name()}
}

// load the declarations of the packages in pkgDirs, in declaration order
func load(ctx context.Context, dir string, pkgDirs []string) ([]*decl, error) {
	patterns := make([]string, len(pkgDirs))
	for i, pkgDir := range pkgDirs {
		rel, err := filepath.Rel(dir, pkgDir)
		if err != nil {
			return nil, err
		}
		patterns[i] = "./" + filepath.ToSlash(rel)
	}
	pkgs, err := packages.Load(&packages.Config{
		Context: ctx,
		Dir:     dir,
		// Syntax type-checks the packages from source
		Mode: packages.NeedName | packages.NeedFiles | packages.NeedSyntax | packages.NeedTypes,
	}, patterns...)
	if err != nil {
		return nil, fmt.Errorf("typegen: unable to load packages: %w", err)
	}
	var errs []error
	var decls []*decl
	for _, pkg := range pkgs {
		for _, err := range pkg.Errors {
			// List errors, like a //go:embed pattern that doesn't match anything
			// before the views are built, don't affect types
			if err.Kind != packages.ListError {
				errs = append(errs, err)
			}
		}
		if len(pkg.GoFiles) == 0 {
			continue
		}
		scope := pkg.Types.Scope()
		for _, name := range scope.Names() {
			if obj, ok := scope.Lookup(name).(*types.TypeName); ok && obj.Exported() {
				decls = append(decls, &decl{obj: obj, file: pkg.Fset.Position(obj.Pos()).Filename})
			}
		}
	}
	if len(errs) > 0 {
		return nil, fmt.Errorf("typegen: unable to load packages: %w", errors.Join(errs...))
	}
	slices.SortFunc(decls, func(a, b *decl) int {
		return cmp.Or(strings.Compare(a.file, b.file), cmp.Compare(a.obj.Pos(), b.obj.Pos()))
	})
	return decls, nil
}

// generate the TypeScript for decls, keyed by the path to write it to
func generate(log *slog.Logger, decls []*decl) (map[string]string, error) {
	byKey := make(map[key]*decl, len(decls))
	for _, d := range decls {
		byKey[keyOf(d.obj)] = d
	}

	// Find what each declaration references and whether json can marshal it
	for _, d := range decls {
		c := &converter{names: func(k key) (string, bool) {
			if _, ok := byKey[k]; !ok {
				return "", false
			}
			d.deps = append(d.deps, k)
			return k.name, true
		}}
		_, d.err = c.declaration(d.obj)
	}

	// Marshaling a type that references a type json can't marshal fails too
	for changed := true; changed; {
		changed = false
		for _, d := range decls {
			if d.err != nil {
				continue
			}
			for _, dep := range d.deps {
				if err := byKey[dep].err; err != nil {
					d.err = fmt.Errorf("it references %s", dep.name)
					changed = true
					break
				}
			}
		}
	}

	// Generate a file for each Go file with types json can marshal
	files := map[string][]*decl{}
	for _, d := range decls {
		if d.err != nil {
			log.Debug("typegen: skipped type", "type", d.obj.Pkg().Path()+"."+d.obj.Name(), "reason", d.err)
			continue
		}
		files[d.file] = append(files[d.file], d)
	}
	outputs := make(map[string]string, len(files))
	for file, fileDecls := range files {
		code, err := generateFile(file, fileDecls, byKey)
		if err != nil {
			return nil, err
		}
		outputs[file+".ts"] = code
	}
	return outputs, nil
}

// generateFile generates the TypeScript for the decls in file, importing the
// types it references from other files
func generateFile(file string, decls []*decl, byKey map[key]*decl) (string, error) {
	// Name each type that's referenced, aliasing imports that collide with
	// other names in the file, e.g. users_User
	names := map[key]string{}
	taken := map[string]bool{}
	for _, d := range decls {
		names[keyOf(d.obj)] = d.obj.Name()
		taken[d.obj.Name()] = true
	}
	imports := map[string][]string{}
	for _, d := range decls {
		for _, dep := range d.deps {
			if _, ok := names[dep]; ok {
				continue
			}
			target := byKey[dep]
			name, spec := dep.name, dep.name
			if taken[name] {
				name = target.obj.Pkg().Name() + "_" + dep.name
				if taken[name] {
					return "", fmt.Errorf("typegen: unable to import %s.%s into %s, since %s is taken", dep.pkg, dep.name, file, name)
				}
				spec = dep.name + " as " + name
			}
			names[dep] = name
			taken[name] = true
			path, err := filepath.Rel(filepath.Dir(file), target.file)
			if err != nil {
				return "", err
			}
			path = filepath.ToSlash(path)
			if !strings.HasPrefix(path, "../") {
				path = "./" + path
			}
			imports[path] = append(imports[path], spec)
		}
	}

	code := new(strings.Builder)
	code.WriteString(header)
	if len(imports) > 0 {
		code.WriteString("\n")
	}
	for _, path := range slices.Sorted(maps.Keys(imports)) {
		fmt.Fprintf(code, "import type { %s } from %q\n", strings.Join(imports[path], ", "), path)
	}
	for _, d := range decls {
		c := &converter{names: func(k key) (string, bool) {
			name, ok := names[k]
			return name, ok
		}}
		ts, err := c.declaration(d.obj)
		if err != nil {
			return "", fmt.Errorf("typegen: unable to generate %s: %w", d.obj.Name(), err)
		}
		fmt.Fprintf(code, "\nexport type %s%s = %s\n", d.obj.Name(), typeParams(d.obj), ts)
	}
	return code.String(), nil
}

// typeParams returns the type parameters of a generic declaration, like <T>
func typeParams(obj *types.TypeName) string {
	var params *types.TypeParamList
	switch t := obj.Type().(type) {
	case *types.Named:
		params = t.TypeParams()
	case *types.Alias:
		params = t.TypeParams()
	}
	if params.Len() == 0 {
		return ""
	}
	names := make([]string, params.Len())
	for i := range params.Len() {
		names[i] = params.At(i).Obj().Name()
	}
	return "<" + strings.Join(names, ", ") + ">"
}

// write the generated files, removing the ones that are no longer generated
func write(outputs map[string]string, existing []string) error {
	for path, code := range outputs {
		data, err := os.ReadFile(path)
		if err == nil {
			if string(data) == code {
				continue
			} else if !strings.HasPrefix(string(data), header) {
				return fmt.Errorf("typegen: won't overwrite %s, since it wasn't generated", path)
			}
		} else if !errors.Is(err, fs.ErrNotExist) {
			return fmt.Errorf("typegen: unable to read %s: %w", path, err)
		}
		if err := os.WriteFile(path, []byte(code), 0644); err != nil {
			return fmt.Errorf("typegen: unable to write %s: %w", path, err)
		}
	}
	for _, path := range existing {
		if _, ok := outputs[path]; ok {
			continue
		}
		data, err := os.ReadFile(path)
		if err != nil {
			return fmt.Errorf("typegen: unable to read %s: %w", path, err)
		}
		if !strings.HasPrefix(string(data), header) {
			continue
		}
		if err := os.Remove(path); err != nil {
			return fmt.Errorf("typegen: unable to remove %s: %w", path, err)
		}
	}
	return nil
}

// converter converts Go types to the TypeScript types of their JSON
type converter struct {
	// names the types that are declared in generated files
	names func(k key) (string, bool)
	// types declared elsewhere that are being inlined, to stop at cycles
	inlining []*types.Named
	// indent of object members
	depth int
}

// declaration returns the TypeScript type of a declared type
func (c *converter) declaration(obj *types.TypeName) (string, error) {
	if obj.IsAlias() {
		return c.typeOf(obj.Type())
	}
	if ts, ok := marshaler(obj.Type()); ok {
		return ts, nil
	}
	// String enums are the union of their constants
	under := obj.Type().Underlying()
	if basic, ok := under.(*types.Basic); ok && basic.Info()&types.IsString != 0 {
		values, err := enum(obj)
		if err != nil {
			return "", err
		} else if len(values) > 0 {
			return strings.Join(values, " | "), nil
		}
	}
	return c.unnamed(under)
}

// enum returns the quoted values of the constants with obj's type
func enum(obj *types.TypeName) (values []string, err error) {
	scope := obj.Pkg().Scope()
	var consts []*types.Const
	for _, name := range scope.Names() {
		if v, ok := scope.Lookup(name).(*types.Const); ok && types.Identical(v.Type(), obj.Type()) {
			consts = append(consts, v)
		}
	}
	slices.SortFunc(consts, func(a, b *types.Const) int {
		return cmp.Compare(a.Pos(), b.Pos())
	})
	for _, c := range consts {
		value, err := jsontext.AppendQuote(nil, constant.StringVal(c.Val()))
		if err != nil {
			return nil, fmt.Errorf("constant %s: %w", c.Name(), err)
		}
		values = append(values, string(value))
	}
	return values, nil
}

func (c *converter) typeOf(t types.Type) (string, error) {
	switch t := types.Unalias(t).(type) {
	case *types.TypeParam:
		return t.Obj().Name(), nil
	case *types.Named:
		return c.named(t)
	default:
		return c.unnamed(t)
	}
}

var errDuration = errors.New("time.Duration needs a `format:` tag option")

func (c *converter) named(t *types.Named) (string, error) {
	switch {
	case isType(t, "time", "Time"):
		return "string", nil
	case isType(t, "time", "Duration"):
		return "", errDuration
	case isType(t, "encoding/json/jsontext", "Value"):
		return "unknown", nil
	}

	// Reference types declared in generated files
	obj := t.Obj()
	if obj.Pkg() != nil && obj.Parent() == obj.Pkg().Scope() {
		if name, ok := c.names(keyOf(obj)); ok {
			if t.TypeArgs().Len() == 0 {
				return name, nil
			}
			args := make([]string, t.TypeArgs().Len())
			for i := range args {
				arg, err := c.typeOf(t.TypeArgs().At(i))
				if err != nil {
					return "", err
				}
				args[i] = arg
			}
			return name + "<" + strings.Join(args, ", ") + ">", nil
		}
	}

	// Inline the rest
	if ts, ok := marshaler(t); ok {
		return ts, nil
	}
	if slices.Contains(c.inlining, t.Origin()) {
		return "unknown", nil
	}
	c.inlining = append(c.inlining, t.Origin())
	defer func() { c.inlining = c.inlining[:len(c.inlining)-1] }()
	return c.unnamed(t.Underlying())
}

func (c *converter) unnamed(t types.Type) (string, error) {
	switch t := t.(type) {
	case *types.Basic:
		info := t.Info()
		switch {
		case info&types.IsBoolean != 0:
			return "boolean", nil
		case info&types.IsString != 0:
			return "string", nil
		case info&types.IsNumeric != 0 && info&types.IsComplex == 0:
			return "number", nil
		}
	case *types.Pointer:
		elem, err := c.typeOf(t.Elem())
		return nullable(elem), err
	case *types.Slice:
		return c.list(t.Elem())
	case *types.Array:
		return c.list(t.Elem())
	case *types.Map:
		// A Go type named Record would shadow TypeScript's Record
		value, err := c.typeOf(t.Elem())
		return "{ [key: string]: " + value + " }", err
	case *types.Struct:
		return c.object(t)
	case *types.Interface:
		return "unknown", nil
	}
	return "", fmt.Errorf("json can't marshal %s", t)
}

// list returns the type of a slice or array with elem
func (c *converter) list(elem types.Type) (string, error) {
	// Bytes are base64 encoded
	if isByte(elem) {
		return "string", nil
	}
	ts, err := c.typeOf(elem)
	if strings.Contains(ts, "|") {
		ts = "(" + ts + ")"
	}
	return ts + "[]", err
}

func (c *converter) object(st *types.Struct) (string, error) {
	fields, fallback, err := structFields(st)
	if err != nil {
		return "", err
	}
	c.depth++
	defer func() { c.depth-- }()
	indent := strings.Repeat("  ", c.depth)
	members := new(strings.Builder)
	for _, f := range fields {
		ts, err := c.fieldType(f.typ, f.options)
		if err != nil {
			return "", fmt.Errorf("field %s: %w", f.goName, err)
		}
		name := f.name
		if !identifier.MatchString(name) {
			quoted, err := jsontext.AppendQuote(nil, name)
			if err != nil {
				return "", fmt.Errorf("field %s: %w", f.goName, err)
			}
			name = string(quoted)
		}
		if f.optional {
			name += "?"
		}
		fmt.Fprintf(members, "%s%s: %s\n", indent, name, ts)
	}
	if fallback != nil {
		ts, err := c.typeOf(fallback)
		if err != nil {
			return "", err
		}
		// Other members would have to match the index signature's type
		if len(fields) > 0 {
			ts = "unknown"
		}
		fmt.Fprintf(members, "%s[key: string]: %s\n", indent, ts)
	}
	if members.Len() == 0 {
		return "{ [key: string]: never }", nil
	}
	return "{\n" + members.String() + strings.Repeat("  ", c.depth-1) + "}", nil
}

var identifier = regexp.MustCompile(`^[A-Za-z_$][A-Za-z0-9_$]*$`)

// fieldType returns the type of a struct field, which its options can change
func (c *converter) fieldType(t types.Type, opts options) (string, error) {
	t = types.Unalias(t)
	if ptr, ok := t.(*types.Pointer); ok {
		elem, err := c.fieldType(ptr.Elem(), opts)
		// Omitted nil pointers are never null
		if opts.omitzero || opts.omitempty {
			return elem, err
		}
		return nullable(elem), err
	}
	switch {
	case isType(t, "time", "Duration"):
		switch opts.format {
		case "":
			return "", errDuration
		case "units", "iso8601":
			return "string", nil
		case "sec", "milli", "micro", "nano":
			return "number", nil
		}
		return "", fmt.Errorf("time.Duration has no %q format", opts.format)
	case isType(t, "time", "Time") && strings.HasPrefix(opts.format, "unix"):
		return "number", nil
	case opts.format == "array" && isBytes(t):
		return "number[]", nil
	case opts.string && isNumber(t):
		return "string", nil
	}
	return c.typeOf(t)
}

// nullable adds null to ts
func nullable(ts string) string {
	if ts == "unknown" || strings.HasSuffix(ts, " | null") {
		return ts
	}
	return ts + " | null"
}

// marshaler returns the type of types with their own JSON or text encoding.
// json marshals addressable values, so methods on *T count.
func marshaler(t types.Type) (string, bool) {
	methods := types.NewMethodSet(types.NewPointer(t))
	switch {
	case methods.Lookup(nil, "MarshalJSONTo") != nil, methods.Lookup(nil, "MarshalJSON") != nil:
		return "unknown", true
	case methods.Lookup(nil, "AppendText") != nil, methods.Lookup(nil, "MarshalText") != nil:
		return "string", true
	}
	return "", false
}

func isType(t types.Type, pkg, name string) bool {
	named, ok := types.Unalias(t).(*types.Named)
	return ok && named.Obj().Pkg() != nil && named.Obj().Pkg().Path() == pkg && named.Obj().Name() == name
}

func isByte(t types.Type) bool {
	basic, ok := t.Underlying().(*types.Basic)
	if !ok || basic.Kind() != types.Uint8 {
		return false
	}
	_, custom := marshaler(t)
	return !custom
}

func isBytes(t types.Type) bool {
	switch t := t.Underlying().(type) {
	case *types.Slice:
		return isByte(t.Elem())
	case *types.Array:
		return isByte(t.Elem())
	}
	return false
}

func isNumber(t types.Type) bool {
	basic, ok := t.Underlying().(*types.Basic)
	return ok && basic.Info()&types.IsNumeric != 0 && basic.Info()&types.IsComplex == 0
}
